    node.strokes = [boundPaint(spec.stroke, node)];
    node.strokeAlign = spec.strokeOutside ? 'OUTSIDE' : 'INSIDE';
    // ANTD EXAM (heal loop): a per-value border style (stylesWhen dashed/dotted) → dashPattern
